import { createTournament, saveTournament, standings, resolvedFixtures, recordAdvancement, formatNRR } from './tournaments.js';
import { listMatches } from './storage.js';

export function tournamentUI({ t, esc, getTournaments, getMatches, refresh, toast, redraw }) {
  const field = (label,name,value,min,max) => `<label class="field">${label}<input name="${name}" type="number" required value="${value}" min="${min}" max="${max}"></label>`;
  function decisionForm(tournament,fixture) {
    return `<form class="stack" data-advancement="${fixture.id}" data-tournament="${tournament.id}"><h3>${t('Organizer advancement decision','සංවිධායකයාගේ ඉදිරි වටයේ තීරණය')}</h3><p class="small muted">${t('The score remains tied. Record an externally decided outcome and its reason. Recorder name is self-reported, not verified. Changing this may invalidate later-round matches.', 'තරග ලකුණු සම ලෙසම පවතී. පිටතදී ගත් තීරණය සහ හේතුව සටහන් කරන්න. සටහන්කරුගේ නම තහවුරු කළ අනන්‍යතාවයක් නොවේ. වෙනස් කිරීමෙන් පසු වටයේ තරගවල ගැටලු ඇති විය හැක.')}</p><label class="field">${t('Advance team','ඉදිරියට යන කණ්ඩායම')}<select name="winner" required><option value="">${t('Choose','තෝරන්න')}</option>${[fixture.teamA,fixture.teamB].map(name=>`<option value="${esc(JSON.stringify(name))}">${esc(name)}</option>`).join('')}<option value="null">${t('Revoke decision — pause advancement','තීරණය අවලංගු කර ඉදිරියට යාම නවත්වන්න')}</option></select></label><label class="field">${t('Reason / tie-break outcome','හේතුව / සම තත්ත්වය විසඳූ ප්‍රතිඵලය')}<input name="reason" required minlength="5" maxlength="300"></label><label class="field">${t('Recorded by','සටහන් කළේ')}<input name="recordedBy" required maxlength="80"></label><p class="form-error" role="alert"></p><button class="btn">${t('Save advancement decision','තීරණය සුරකින්න')}</button></form>`;
  }
  function knockout(tournament,matches) {
    const fixtures=resolvedFixtures(tournament,matches), champion=fixtures.at(-1)?.winner;
    return `<div class="page-head"><div><span class="eyebrow">KNOCKOUT</span><h1>${esc(tournament.name)}</h1></div><a class="btn" href="#tournaments">${t('All tournaments','තරගාවලි සියල්ල')}</a></div><p class="notice">${t('Winners advance automatically. Byes are awarded in team-entry order. Tied matches pause until an organizer records an advancement decision. Super-over scoring is not available yet.', 'ජයග්‍රාහකයන් ඊළඟ වටයට යයි. Teams ඇතුළත් කළ අනුපිළිවෙළට byes ලැබේ. සම තරගවලදී සංවිධායක තීරණයක් සටහන් කරන තුරු bracket එක නවතී. Super-over scoring තවම නැහැ.')}</p>${champion?`<section class="card spacer"><span class="badge">${t('CHAMPION','ශූරයා')}</span><h2>${esc(champion)}</h2></section>`:''}<section class="stack spacer">${fixtures.map((f,index)=>{const match=matches.find(m=>m.id===f.id);return `<article class="card stack"><span class="badge neutral">${index===fixtures.length-1?t('Final','අවසන් තරගය'):t('Round','වටය')+' '+f.round}</span><h3>${esc(f.teamA||t('Awaiting winner','ජයග්‍රාහකයා තවම නැහැ'))} · ${esc(f.teamB||(f.bye?t('Bye','නිතරග ජය'):t('Awaiting winner','ජයග්‍රාහකයා තවම නැහැ')))}</h3>${f.conflict?`<p class="form-error">${t('An earlier result changed. This match is preserved but cannot advance or be scored until the earlier result is restored.', 'පෙර ප්‍රතිඵලයක් වෙනස් වී ඇත. මෙම තරගය සුරැකී ඇත; පෙර ප්‍රතිඵලය යථා තත්ත්වයට පත් වන තුරු scoring සහ ඉදිරියට යාම නවතී.')}</p>`:f.bye?`<p>${esc(f.winner)} — ${t('advances with a bye','නිතරගයෙන් ඊළඟ වටයට')}</p>`:f.waiting?`<p class="muted">${t('Waiting for earlier results','පෙර තරග ප්‍රතිඵල බලාපොරොත්තුවෙන්')}</p>`:''}${f.tied?`<p>${f.decision?t('Tied score — organizer decision applied.','සම ලකුණු — සංවිධායක තීරණය යොදා ඇත.'):t('Match tied — no winner advanced.','තරගය සමයි — කිසිවෙකු ඊළඟ වටයට යවා නැත.')}</p>${decisionForm(tournament,f)}`:''}${f.winner&&!f.bye?`<p>${t('Winner','ජයග්‍රාහකයා')}: ${esc(f.winner)}</p>`:''}${f.ready?`<a class="btn" href="#${match?'score':'new'}/${f.id}">${match?t('Open match','තරගය විවෘත කරන්න'):t('Set up match','තරගය සකසන්න')}</a>`:''}</article>`;}).join('')}</section><section class="card stack spacer"><h2>${t('Advancement history','ඉදිරි වට තීරණ ඉතිහාසය')}</h2>${(tournament.decisions||[]).map(d=>`<div><strong>${esc(d.winner||t('Decision revoked','තීරණය අවලංගුයි'))}</strong><p>${esc(d.reason)}</p><small>${esc(d.recordedBy)} · ${esc(new Date(d.at).toLocaleString())} · ${esc(d.fixtureId)}</small></div>`).join('')||`<p>${t('No decisions recorded.','තීරණ සටහන් කර නැහැ.')}</p>`}</section>`;
  }
  function render(id) {
    const tournaments = getTournaments(), tournament = tournaments.find(v => v.id === id);
    if (id && !tournament) return `<div class="notice">${t('Tournament not found on this device.', 'තරගාවලිය මෙම උපාංගයේ නැහැ.')} <a href="#tournaments">${t('Back','ආපසු')}</a></div>`;
    if (tournament?.format === 'knockout') return knockout(tournament,getMatches());
    if (tournament) {
      const matches = getMatches(), rows = standings(tournament,matches);
      return `<div class="page-head"><div><span class="eyebrow">${t('LEAGUE','ලීග්')}</span><h1>${esc(tournament.name)}</h1><p>${tournament.teams.length} ${t('teams','කණ්ඩායම්')} · ${tournament.overs} ${t('overs','ඕවර')} · ${esc(tournament.ballType)}</p></div><a class="btn" href="#tournaments">${t('All tournaments','තරගාවලි සියල්ල')}</a></div><section class="card stack"><h2>${t('Points','ලකුණු')}</h2><p class="muted small">${t('Win: 2 · Tie: 1 · Loss: 0. Order: points, then NRR; exact ties shown alphabetically. NRR uses completed matches and each match’s balls per over. All-out innings use the full quota. — means no calculable rate yet. DLS/revised targets are not supported.', 'ජය: 2 · සම: 1 · පරාජය: 0. පිළිවෙළ: ලකුණු, ඉන්පසු NRR; දෙකම සම නම් අකාරාදීව. අවසන් තරග සහ එක් එක් තරගයේ ඕවරයක පන්දු ගණන භාවිත වේ. All-out සඳහා සම්පූර්ණ ඕවර ගණන ගනී. — යනු තවම ගණනය කළ නොහැක. DLS/revised targets තවම නැහැ.')}</p><div class="table-wrap"><table><thead><tr>${[t('Team','කණ්ඩායම'),t('Played','තරග'),t('Won','ජය'),t('Lost','පරාජ'),t('Tied','සම'),t('Points','ලකුණු'),'NRR'].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.played}</td><td>${r.won}</td><td>${r.lost}</td><td>${r.tied}</td><td><strong>${r.points}</strong></td><td>${formatNRR(r.nrr)}</td></tr>`).join('')}</tbody></table></div></section><section class="stack spacer"><h2>${t('Fixtures','තරග ලැයිස්තුව')}</h2>${tournament.fixtures.map(f => { const match = matches.find(m=>m.id===f.id); return `<article class="card"><span class="badge neutral">${t('Round','වටය')} ${f.round}</span><h3>${esc(f.teamA)} · ${esc(f.teamB)}</h3><a class="btn ${match?'':'primary'}" href="#${match?'score':'new'}/${f.id}">${match?t('Open match','තරගය විවෘත කරන්න'):t('Set up match','තරගය සකසන්න')}</a></article>`; }).join('')}</section>`;
    }
    return `<div class="page-head"><h1>${t('Tournaments','තරගාවලි')}</h1></div><p class="notice">${t('League and knockout tournaments are saved on this device. Cloud tournament backup and group stages are not available yet. Teams and fixtures lock at creation.', 'League සහ knockout තරගාවලි මෙම උපාංගයේ සුරැකේ. Cloud tournament backup සහ group stages තවම නැහැ. සෑදූ පසු teams සහ fixtures වෙනස් කළ නොහැක.')}</p><div class="home-grid"><section class="stack">${tournaments.map(v=>`<article class="card"><h2>${esc(v.name)}</h2><p>${v.teams.length} ${t('teams','කණ්ඩායම්')} · ${v.format==='knockout'?v.teams.length-1:v.fixtures.length} ${t('matches','තරග')} · ${esc(v.format)}</p><a class="btn" href="#tournaments/${v.id}">${t('Fixtures and points','තරග සහ ලකුණු')}</a></article>`).join('') || `<div class="card">${t('Create your first tournament.','ඔබේ පළමු තරගාවලිය සාදන්න.')}</div>`}</section><form id="tournament-form" class="card stack"><h2>${t('Create tournament','තරගාවලියක් සාදන්න')}</h2><label class="field">${t('Format','ආකෘතිය')}<select name="format"><option value="league">League</option><option value="knockout">Knockout</option></select></label><label class="field">${t('Tournament name','තරගාවලියේ නම')}<input name="name" required maxlength="80"></label><label class="field">${t('Teams — one per line (2–16)','කණ්ඩායම් — පේළියකට එක බැගින් (2–16)')}<textarea name="teams" rows="6" maxlength="1296" required></textarea></label><label class="field">${t('Ball type','පන්දු වර්ගය')}<select name="ballType"><option value="softball">Softball</option><option value="hardball">Hardball</option></select></label><div class="fields">${field(t('Overs','ඕවර'),'overs',6,1,50)}${field(t('Balls per over','ඕවරයක පන්දු'),'ballsPerOver',6,1,12)}${field(t('Players per team','කණ්ඩායමක ක්‍රීඩකයන්'),'players',8,2,22)}</div><p class="small muted">${t('League: every pair plays once. Knockout: winners advance, with byes for extra slots. Enter teams in seed order. Players and toss are entered at match setup.', 'League: සියලු කණ්ඩායම් එකිනෙකා සමඟ තරග කරයි. Knockout: ජයග්‍රාහකයා ඉදිරියට යයි. Teams seed අනුපිළිවෙළට ඇතුළත් කරන්න. Players සහ toss තරගය සකසන විට දෙන්න.')}</p><p class="form-error" role="alert"></p><button class="btn primary">${t('Create fixtures','තරග ලැයිස්තුව සාදන්න')}</button></form></div>`;
  }
  function bind() {
    document.querySelectorAll('[data-advancement]').forEach(form => {
      let saving = false;
      form.onsubmit = async event => {
        event.preventDefault(); if (saving) return; saving = true;
        const button = form.querySelector('button'); button.disabled = true;
        try {
          const tournament = getTournaments().find(v => v.id === form.dataset.tournament);
          const values = Object.fromEntries(new FormData(form));
          const updated = recordAdvancement(tournament,await listMatches(),{...values,fixtureId:form.dataset.advancement,winner:JSON.parse(values.winner)});
          await saveTournament(updated,tournament.revision || 0);
          await refresh(); redraw(); toast(t('Advancement decision saved','ඉදිරි වටයේ තීරණය සුරැකුණා'));
        } catch(error) { form.querySelector('.form-error').textContent = error.message; }
        finally { saving = false; button.disabled = false; }
      };
    });
    const form = document.querySelector('#tournament-form'); if (!form) return;
    let saving = false;
    form.onsubmit = async event => {
      event.preventDefault(); if (saving) return; saving = true;
      const submit = form.querySelector('button'); submit.disabled = true;
      try {
        const values = Object.fromEntries(new FormData(form));
        const tournament = createTournament({...values, teams:values.teams.split(/\r?\n/)});
        await saveTournament(tournament); await refresh(); location.hash = '#tournaments/' + tournament.id;
        toast(t('Tournament saved','තරගාවලිය සුරැකුණා'));
      } catch(error) { form.querySelector('.form-error').textContent = error.message; }
      finally { saving = false; submit.disabled = false; }
    };
  }
  return { render, bind };
}
